def general_payment_events_iso_day(value):
    return type(value) is str and len(value) == 10 and value[4] == '-' and value[7] == '-' and value[:4].isdigit() and value[5:7].isdigit() and value[8:].isdigit()

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    payments = view.get('payments')
    boundaries = view.get('annual_income_boundaries')
    if type(payments) is not list or type(boundaries) is not list:
        return part(facts, [], witnesses, False, reasons + ['general_payment_channels_unread'])
    pt = target_payment(kernel)
    st = target_service(kernel)
    payment_matches = 0
    service_matches = 0
    linked_count = 0
    seen = set()
    for index, record in enumerate(payments):
        evidence = checked(record, public, True)
        local_id = record.get('local_id')
        term = record.get('payment_term')
        payer = record.get('payer')
        payer_text = record.get('payer_text')
        payees = record.get('payees')
        payee_texts = record.get('payee_texts')
        amount = record.get('amount')
        precision = record.get('temporal_precision')
        date = record.get('payment_date')
        year = record.get('stated_year')
        valid = evidence is not None and type(local_id) is str and local_id not in seen and type(term) is str
        valid = valid and (payer is None or type(payer) is str) and ((payer is None and payer_text is None) or (type(payer) is str and type(payer_text) is str))
        valid = valid and type(payees) is list and len(payees) > 0 and all(type(x) is str for x in payees)
        valid = valid and type(payee_texts) is list and len(payee_texts) == len(payees) and all(type(x) is str for x in payee_texts)
        valid = valid and (amount is None or type(amount) in (int, float)) and precision in ('full_date', 'year_only', 'unstated')
        if not valid:
            complete = False
            continue
        quote = ' '.join(row['quote'].lower() for row in evidence)
        if term.lower() not in quote or not all(text.lower() in quote for text in payee_texts) or (payer is not None and payer_text.lower() not in quote):
            complete = False
            add(reasons, 'payment_roles_not_source_explicit')
            continue
        if precision == 'full_date' and not general_payment_events_iso_day(date):
            complete = False
            add(reasons, 'payment_date_not_explicit_full_date')
            continue
        if precision == 'year_only' and (type(year) is not int or date is not None):
            complete = False
            add(reasons, 'payment_year_is_not_payment_day')
            continue
        if precision == 'unstated' and (date is not None or year is not None):
            complete = False
            continue
        linked = record.get('linked_service')
        if linked is not None:
            worker = linked.get('worker') if type(linked) is dict else None
            employer = linked.get('employer') if type(linked) is dict else None
            worker_text = linked.get('worker_text') if type(linked) is dict else None
            employer_text = linked.get('employer_text') if type(linked) is dict else None
            service_term = linked.get('service_term') if type(linked) is dict else None
            valid_link = all(type(x) is str for x in (worker, employer, worker_text, employer_text, service_term))
            valid_link = valid_link and worker in payees and (payer is None or payer == employer)
            valid_link = valid_link and worker_text.lower() in quote and employer_text.lower() in quote and service_term.lower() in quote
            if not valid_link:
                complete = False
                add(reasons, 'linked_service_roles_not_source_coherent')
                continue
        seen.add(local_id)
        for row in evidence:
            add(witnesses, row)
        payment = 'general_payment_' + str(index)
        if record.get('is_query_payment') is True:
            payment_matches += 1
            if type(pt) is str:
                payment = pt
        put(facts, 'payment_', [payment])
        if type(payer) is str:
            put(facts, 'agent_', [payment, payer])
        for payee in payees:
            put(facts, 'patient_', [payment, payee])
        if type(amount) in (int, float):
            put(facts, 'amount_', [payment, amount])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [payment, record.get('medium')])
        if precision == 'full_date':
            put(facts, 'start_', [payment, date])
        if type(linked) is dict:
            linked_count += 1
            service = 'general_payment_service_' + str(index)
            if linked.get('is_query_service') is True:
                service_matches += 1
                if type(st) is str:
                    service = st
            put(facts, 'service_', [service])
            put(facts, 'agent_', [service, linked.get('worker')])
            put(facts, 'patient_', [service, linked.get('employer')])
            if type(linked.get('service_kind')) is str:
                put(facts, 'purpose_', [service, linked.get('service_kind')])
            if type(linked.get('service_venue')) is str:
                put(facts, 'location_', [service, linked.get('service_venue')])
            if type(linked.get('location')) is str:
                put(facts, 'location_', [service, linked.get('location')])
                if type(linked.get('country')) is str:
                    put(facts, 'country_', [linked.get('location'), linked.get('country')])
            if type(linked.get('start_date')) is str:
                put(facts, 'start_', [service, linked.get('start_date')])
            if type(linked.get('end_date')) is str:
                put(facts, 'end_', [service, linked.get('end_date')])
            put(facts, 'purpose_', [payment, service])
        elif type(record.get('purpose_entity')) is str:
            put(facts, 'purpose_', [payment, record.get('purpose_entity')])
    for record in boundaries:
        if not support(witnesses, record, public, True) or type(record.get('person')) is not str or type(record.get('year')) is not int:
            complete = False
    if type(pt) is str and len(payments) > 0 and payment_matches != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if type(st) is str and linked_count > 0 and service_matches != 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, [], witnesses, complete, reasons)

def payment_service_events_iso_day(value):
    return type(value) is str and len(value) == 10 and value[4] == '-' and value[7] == '-' and value[:4].isdigit() and value[5:7].isdigit() and value[8:].isdigit()

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    payments = view.get('payments')
    services = view.get('services')
    boundaries = view.get('annual_income_boundaries')
    if type(payments) is not list or type(services) is not list or type(boundaries) is not list:
        return part(facts, [], witnesses, False, reasons + ['payment_or_service_channels_unread'])
    payment_rows = {}
    for record in payments:
        evidence = checked(record, public, True)
        local_id = record.get('local_id')
        payer = record.get('payer')
        payer_text = record.get('payer_text')
        payees = record.get('payees')
        payee_texts = record.get('payee_texts')
        term = record.get('payment_term')
        precision = record.get('temporal_precision')
        date = record.get('payment_date')
        year = record.get('stated_year')
        amount = record.get('amount')
        valid = evidence is not None and type(local_id) is str and local_id not in payment_rows and type(term) is str
        valid = valid and (payer is None or type(payer) is str) and ((payer is None and payer_text is None) or (type(payer) is str and type(payer_text) is str))
        valid = valid and type(payees) is list and len(payees) > 0 and all(type(x) is str for x in payees)
        valid = valid and type(payee_texts) is list and len(payee_texts) == len(payees) and all(type(x) is str for x in payee_texts)
        valid = valid and (amount is None or type(amount) in (int, float)) and precision in ('full_date', 'year_only', 'unstated')
        if not valid:
            complete = False
            continue
        quote = ' '.join(row['quote'].lower() for row in evidence)
        if term.lower() not in quote or not all(text.lower() in quote for text in payee_texts) or (payer is not None and payer_text.lower() not in quote):
            complete = False
            add(reasons, 'payment_roles_not_source_explicit')
            continue
        if precision == 'full_date' and not payment_service_events_iso_day(date):
            complete = False
            add(reasons, 'payment_date_not_explicit_full_date')
            continue
        if precision == 'year_only' and (type(year) is not int or date is not None):
            complete = False
            add(reasons, 'payment_year_is_not_payment_day')
            continue
        if precision == 'unstated' and (date is not None or year is not None):
            complete = False
            continue
        payment_rows[local_id] = {'record': record, 'evidence': evidence}
    service_ids = {}
    service_matches = 0
    st = target_service(kernel)
    for index, record in enumerate(services):
        evidence = checked(record, public, True)
        local_id = record.get('local_id')
        worker = record.get('worker')
        employer = record.get('employer')
        worker_text = record.get('worker_text')
        employer_text = record.get('employer_text')
        term = record.get('service_term')
        basis = record.get('source_basis')
        linked = record.get('linked_payment_local_id')
        valid = evidence is not None and type(local_id) is str and local_id not in service_ids
        valid = valid and all(type(x) is str for x in (worker, employer, worker_text, employer_text, term))
        valid = valid and basis in ('explicit_service', 'payment_for_service')
        if not valid:
            complete = False
            continue
        quote = ' '.join(row['quote'].lower() for row in evidence)
        if worker_text.lower() not in quote or employer_text.lower() not in quote or term.lower() not in quote:
            complete = False
            add(reasons, 'service_roles_not_source_explicit')
            continue
        if basis == 'payment_for_service':
            if type(linked) is not str or linked not in payment_rows:
                complete = False
                add(reasons, 'service_payment_link_unread')
                continue
            payment_record = payment_rows[linked]['record']
            if payment_record.get('service_local_id') != local_id or worker not in payment_record.get('payees') or (type(payment_record.get('payer')) is str and payment_record.get('payer') != employer):
                complete = False
                add(reasons, 'payment_service_roles_not_coherent')
                continue
        elif linked is not None:
            complete = False
            continue
        service = 'source_service_' + str(index)
        if record.get('is_query_service') is True:
            service_matches += 1
            if type(st) is str:
                service = st
        service_ids[local_id] = service
        for row in evidence:
            add(witnesses, row)
        put(facts, 'service_', [service])
        put(facts, 'agent_', [service, worker])
        put(facts, 'patient_', [service, employer])
        if type(record.get('service_kind')) is str:
            put(facts, 'purpose_', [service, record.get('service_kind')])
        if type(record.get('service_venue')) is str:
            put(facts, 'location_', [service, record.get('service_venue')])
        if type(record.get('location')) is str:
            put(facts, 'location_', [service, record.get('location')])
            if type(record.get('country')) is str:
                put(facts, 'country_', [record.get('location'), record.get('country')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [service, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [service, record.get('end_date')])
    pt = target_payment(kernel)
    payment_matches = 0
    for index, local_id in enumerate(payment_rows):
        row = payment_rows[local_id]
        record = row['record']
        evidence = row['evidence']
        linked = record.get('service_local_id')
        if linked is not None and linked not in service_ids:
            complete = False
            add(reasons, 'payment_links_unknown_service')
            continue
        payment = 'source_payment_' + str(index)
        if record.get('is_query_payment') is True:
            payment_matches += 1
            if type(pt) is str:
                payment = pt
        for item in evidence:
            add(witnesses, item)
        put(facts, 'payment_', [payment])
        if type(record.get('payer')) is str:
            put(facts, 'agent_', [payment, record.get('payer')])
        for payee in record.get('payees'):
            put(facts, 'patient_', [payment, payee])
        if type(record.get('amount')) in (int, float):
            put(facts, 'amount_', [payment, record.get('amount')])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [payment, record.get('medium')])
        if record.get('temporal_precision') == 'full_date':
            put(facts, 'start_', [payment, record.get('payment_date')])
        if type(linked) is str:
            put(facts, 'purpose_', [payment, service_ids[linked]])
    for record in boundaries:
        if not support(witnesses, record, public, True) or type(record.get('person')) is not str or type(record.get('year')) is not int:
            complete = False
    if type(st) is str and len(services) > 0 and service_matches != 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if type(pt) is str and len(payments) > 0 and payment_matches != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, [], witnesses, complete, reasons)
